-- A sheet's pot (two decimals), not dated: each member of a balanced pool shows its cut of it. Null
-- (blank) is none.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(19, 2);
    /** The fiscal year start month, 1 to 12: a fiscal year runs twelve months from the first of it. */
    @Column(name = "fiscal_start_month", nullable = false)
    private int fiscalStartMonth = 1;

    /** The entry date: while set, a new claim given no date is dated it rather than the sheet's
     *  today; null for off. */
    @Column(name = "entry_date")
    private LocalDate entryDate;

    /** The pot: each member of a balanced pool shows a cut of it; null for none. */
    @Column(name = "pot", precision = 19, scale = 2)
    private BigDecimal pot;

    /** The parent sheet's id: a grade with no rate in force on a date on this sheet takes the
     *  parent's; null for none. */
    @Column(name = "parent_id")
    public void setEntryDate(LocalDate entryDate) {
        this.entryDate = entryDate;
    }

    public BigDecimal getPot() {
        return pot;
    }

    public void setPot(BigDecimal pot) {
        this.pot = pot;
    }

    public String getParentId() {
        rollups.recordAll(to, user);
    }

    private void copy(String from, String to) {
        jdbc.update("INSERT INTO sheet (id, today, last_claim_number, last_batch_number, policy_date,"
                + " period_numbering_from, grace_days, entry_date, pot, parent_id, archived, fiscal_start_month)"
                + " SELECT ?, today, 0, 0, policy_date, period_numbering_from, grace_days, entry_date, pot, parent_id,"
                + " FALSE, fiscal_start_month FROM sheet WHERE id = ?", to, from);
        LocalDate today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", LocalDate.class, to);

        // The sheet's own lists: settings, roles, rates, holidays, void reasons, templates and periods.

